from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MODULES={
'冷鏈':('採收後組織仍持續呼吸與蒸散；降溫可減少儲存物耗損、延緩衰老與病原生長，但溫度不得低於該品種的寒害閾值。必須先移除田間熱，再連續維持冷鏈；包裝保濕與足夠通氣須同時兼顧。','例如葉菜適用接近 0°C 的低溫，而成熟綠番木瓜、香蕉等熱帶果實需較高溫，不能混用同一冷藏設定。'),
'預冷':('預冷是快速移除田間熱，而非單純將貨物放進冷庫。冷卻速度受產品大小、表面積、堆裝方式及傳熱途徑影響。壓差預冷以強制氣流穿過箱內，真空預冷以減壓蒸發吸熱，水冷則靠冷水接觸傳熱。','例如結球萵苣表面積大適合真空預冷，多種果實共同包裝場則常以壓差預冷較通用；真空法用於大果可能冷卻慢且失水。'),
'水分':('水由高水勢向低水勢移動，根、木質部、葉片與大氣形成連續梯度。缺水會先抑制膨壓與細胞擴張，再影響氣孔、光合作用和產量；積水則可因根缺氧造成吸水能力下降。因此管理應依根域監測而非只看地表乾濕。','例如文旦快速膨大期須供足水，採前適度減水可提高糖度，但嚴重缺水造成落葉與小果，並非有利品質。'),
'RDI':('RDI 是按生育階段設定可控制的輕度缺水，利用細胞膨大比光合作用對缺水更敏感的特性，減少過旺營養生長或果肉稀釋，並引發滲透調節。應監測土壤含水、樹體水勢、果徑及落葉，避免越過不可逆傷害門檻。','麻豆文旦宜於膨大趨緩的採前階段試行適度限灌；花期、幼果與快速膨大期需水敏感，不宜任意斷水。'),
'礦養':('缺素診斷須同時看新老葉、葉脈與葉緣、果實及生長點，並考慮元素在韌皮部中的再移動性。氮、鉀、鎂等可移動元素多先影響老葉；鈣、鐵等難再移動元素常先影響新生組織。最後以葉片與土壤分析佐證。','例如缺鎂先見老葉脈間黃化，缺鐵則多見幼葉脈間黃化；新葉壞死也可能是鹽害、根傷或病害，不可僅憑一個徵狀下結論。'),
'硼':('硼參與細胞壁果膠交聯、分生組織生長及生殖發育，缺乏時幼嫩組織脆裂、頂芽受損、花粉萌芽與花粉管生長受阻。硼的缺乏與毒害範圍相近，須經分析後少量均勻補充，並改善根域乾濕與 pH。','番木瓜缺硼可見葉柄龜裂流膠、果面凹凸瘤狀；柑橘可出現硬果、膠化與種子發育異常。'),
'鈣':('鈣維持細胞壁與細胞膜穩定，也參與細胞訊號。其在韌皮部再移動性低，果實蒸散又弱，因此土壤不缺鈣仍可能因水分波動、根傷、高銨或旺長競爭而局部缺鈣。改善供水及負載、抑制過旺生長比一味加肥更重要。','蘋果苦痘病、番茄尻腐與部分芒果軟鼻均與果實局部鈣供應失衡有關；對果實直接補鈣須考慮表皮吸收與藥害。'),
'糖運輸':('成熟葉為源，果實等生長或貯藏組織為庫。糖經葉肉、伴細胞與篩管裝載，在源端滲透吸水建立膨壓，依壓力流送往庫端，再經共質體或質外體卸載；庫端糖的分解、利用及液泡貯藏維持輸入梯度。','例如疏果可提高每果可分得的同化物，但疏果過度會減產；果實轉化酶活性與細胞數等共同影響庫強，不能只以葉片糖濃度預測產量。'),
'糖酵素':('轉化酶將蔗糖水解為葡萄糖與果糖；蔗糖合成酶催化可逆反應，但在許多庫組織主要參與蔗糖裂解；蔗糖磷酸合成酶參與蔗糖合成。各酵素的組織位置、發育時期與運輸、液泡貯藏共同決定糖組成。','例如酸性轉化酶較強的果實常較易累積己糖；蔗糖累積型果實可能於成熟時提高合成、降低裂解，但不能由單一酵素活性斷定全部糖度。'),
'休眠':('芽休眠分相關休眠、內生休眠與環境休眠，分別受其他器官、芽自身生理與外界不利條件限制。需冷量是解除內生休眠所需的有效低溫累積，之後仍須足夠熱量才能萌芽，不能把一次寒流等同完成需冷。','摘心可解除腋芽相關休眠，冬季冷量可解除溫帶果樹內生休眠，回暖則解除環境限制；三者的解除方法不同。'),
'產調':('產期調節必須先掌握花芽形成的位置、誘導條件與枝梢成熟度，再用修剪、光週期、溫度、灌溉及適當調節物質改變萌芽與開花。必須保留足夠葉面積並管理負載，否則短期提前採收會耗損翌期產能。','葡萄可利用成熟結果母枝修剪後再萌芽結果；鳳梨可在植株成熟後用乙烯誘花，兩者的原理不能互相套用。'),
'乙烯':('乙烯與受體結合後，解除受體對下游訊號的抑制，經 EIN2、EIN3 等路徑調節相關基因。更年性果實可形成自催化乙烯及呼吸高峰，進一步促進軟化、轉色與香氣形成；效果受果齡、溫度、濃度及暴露時間限制。','香蕉可用適當乙烯整齊催熟；1-MCP 阻斷乙烯感受可延緩部分果實成熟，但過度處理可能造成後熟與風味異常。'),
'無子':('單為結果不需要受精便可形成果實；種子敗育型則曾受精，胚或胚乳後來停止發育，常殘留種痕。無融合生殖是不經正常有性受精而產生胚，仍可形成有種子的果實，因此不可將三者混為一談。','香蕉可作單為結果例，許多無子葡萄為種子敗育例，柑橘珠心胚則是無融合生殖例；有子葡萄無子化處理須依品種精確掌握花期。'),
'育種':('多年生果樹常有幼年期長、株體大、世代慢、高雜合與自交不親和等限制。育種應先訂明確目標、評估親本、設計雜交或選拔，再經多地多季及採後試驗；組培、胚救援與標誌可加速，但不能代替農藝驗證。','例如以 SNP 或 SSR 追蹤抗病等位基因，可在幼苗期淘汰不帶目標者；芽變可快速改變果色，但仍須檢查嵌合與性狀穩定性。'),
'樹冠':('果園產量取決於單位土地截光、光能利用與同化物分配，而非單株大小。適當樹形讓葉片獲有效光，並減少維持巨大骨幹與徒長枝的消耗；需配合枝條角度、疏枝、負載與根域管理。','矮砧蘋果細長紡錘形有利早期密植與採收，但過密仍會陰蔽、著色不良，並需要支架與精準肥水。'),
'IPM':('整合病蟲管理以監測與正確診斷為起點，結合健康種苗、清園、抗性品種、物理阻隔、天敵與適期用藥。目標是在可接受的經濟損失下維持生產、保護天敵並減少抗藥性；不追求完全沒有昆蟲。','網室番木瓜可降低蚜蟲傳毒，但應修補破口、控制入苗來源與內部害蟲；殺蟲劑亦須輪替作用機制，不能因有網便停止巡查。'),
'環控':('設施透過覆蓋與環控改變光、溫、濕、風及水分，能降低露地不確定性，但也可能積熱、遮光、鹽化及增加特定病蟲。設計應以作物需求、通風換氣、排水、耐風及成本效益整合評估。','中部葡萄避雨可減裂果與病害；若通風不足，夏季葉溫過高仍會降低著色、光合與花芽品質。'),
'根域':('根域 pH、通氣、鹽分及水分共同限制養分吸收；淹水缺氧會使 ATP 供應與離子運輸下降，厭氧代謝及根腐風險升高。排水、測土施肥、成熟有機質及避免土壤壓實，是比單次增肥更根本的措施。','坡地果園可採等高線排水、草生與局部覆蓋，低窪地可高畦加明暗溝；土壤檢查應包含剖面硬盤與地下水位。'),
'種子':('種子壽命受遺傳、含水量、溫度與氧化損傷影響。多數蔬菜屬可乾燥貯藏的正儲型種子，以低含水、低溫及防潮密封延長壽命；活力下降通常早於標準發芽率明顯降低，應結合活力與健康檢測。','加速老化測試可比較劣化耐受性；電導度高表示浸種液電解質滲漏多；TTC 以活組織酵素還原顯色判斷生活力，三者不是完全同一指標。'),
'育苗':('健康苗需從健康母本或種子、潔淨介質、消毒容器及隔離環境開始，培育後仍須病原檢測、分級與追溯。組培出瓶苗必須逐步降低濕度、增加光與通風，使角質層、氣孔與根系適應外界。','馬鈴薯莖頂脫毒後生產微型薯，再經隔離繁殖與檢測擴繁種薯；僅外觀無病或經過組培，均不能直接保證無病毒。'),
'繁殖':('無性繁殖可保存優良基因型，卻也可能傳播病毒並累積體細胞變異。扦插需在未生根階段降低蒸散、維持葉片碳供應與基部氧氣；嫁接則須親和、形成層對準、保濕固定並重建維管束。','菊花可用健康母株插穗在間歇噴霧下發根；蝴蝶蘭可用芽或 PLB 組培量產，但過多繼代需監測變異與病原。'),
'光週期':('光週期反應多由葉片感受連續暗期，經光受體與生理時鐘形成促花／抑花訊號，傳向莖頂。短日植物通常需要長而不中斷的夜，暗期中斷可延遲其成花；長日植物則常可因夜間補光促花。','菊花及聖誕紅可用遮光促花、夜間補光延遲，洋桔梗多為量性長日；品種、溫度與苗齡會改變反應強度。'),
'春化':('春化是一定低溫暴露使植物取得成花能力，並非立即開花。種子型可在吸水種子或幼苗感受，綠體型則需先達一定大小；其後仍可能需要合適日長及溫度，過早受冷也會造成蔬菜未熟抽薹。','甘藍、洋蔥等許多品種須達一定苗齡才有效感冷；部分白菜、蘿蔔在較早階段即可春化，故育苗溫度與播期非常重要。'),
'花色':('花色取決於色素種類、比例、細胞位置及結構，並受液泡 pH、金屬離子、共色素與表皮光學性質影響。花青素、類胡蘿蔔素與甜菜色素等有限類別，可因基因調控與細胞環境形成大量色彩。','繡球藍色涉及花青素與可利用鋁，酸性根域只是促進鋁有效性的條件；白花若缺相應色素，單改 pH 不會必然變藍。'),
'切花':('切花採後品質由水分平衡、碳源、病原及衰老共同決定。氣泡與微生物堵管會使吸水低於蒸散；糖可供呼吸與開花，卻也可滋生菌，因此保鮮液常結合糖、酸化與抑菌，乙烯敏感種類另需抗乙烯處理。','香石竹宜避乙烯並用適當抗乙烯措施；熱帶火鶴花則須同時避免過低溫與粗糙碰撞，不能把溫帶切花低溫設定直接套用。'),
'介質':('理想介質須同時提供適量空氣、有效水、養分緩衝與根系支撐，並具有適合 pH、低鹽、結構穩定與無病蟲等條件。配方應依盆高、容器大小、灌溉方式及作物需求決定，不能只靠一個固定材料比例。','泥炭／椰纖增加保水，珍珠石與樹皮增加通氣；較淺穴盤更易缺氧，若使用高保水材料，需降低灌水頻率並檢查排水。'),
'雜草':('雜草會競爭資源、寄藏病蟲、妨礙作業並增加種子庫。有效管理需把預防、輪作、覆蓋、假播種床、機械與必要化學方法整合，尤其掌握幼苗競爭敏感期，並在雜草結籽前處理。','草生果園可刈草保留適量地表覆蓋；短期蔬菜幼苗較弱，畦面須及早除草，但不應把所有草生管理一律當成有害。'),
'氮肥':('氮參與胺基酸、蛋白質與葉綠素合成；硝態氮需還原後經 GS/GOGAT 同化，銨態氮可直接進入同化但過量會毒害與酸化根域。施肥須按需分次，並考慮光量與碳骨架供應，避免未同化硝酸鹽累積。','弱光葉菜過量施硝態氮容易提高硝酸鹽；番茄結果期宜避免高銨及過氮，以減少 Ca、K 等吸收失衡、徒長及尻腐風險。'),
'採後菜':('蔬菜含水高、組織嫩且採後仍代謝，截切又會提高呼吸、傷口滲出與微生物風險。品質控制需採前衛生、輕採遮蔭、快速預冷、潔淨清洗、適度脫水、透氣保濕包裝與不中斷冷鏈共同完成。','即食萵苣應以飲用水品質與經驗證程序清洗消毒，避免交叉污染；清洗不是滅菌，氣調包裝也不可取代冷藏。'),
'F1':('F1 育種先建立與維持親本純度，再用配合力試驗找出優良組合，最後以可控制授粉方式製種並做純度與發芽檢驗。雜種優勢依組合與性狀而異；F1 可結種，但 F2 分離後通常難維持同樣整齊度。','瓜類可用人工去雄／去雄花與定向授粉製種；十字花科可利用自交不親和或雄不稔，仍須排除外來花粉及親本自交混雜。'),
'MAS':('分子標誌是可檢測的遺傳多型性，如 SNP、SSR。與目標基因緊密連鎖或本身為功能變異時，可在幼苗期選拔，也可追蹤回交背景與聚合多個基因；限制包括重組、族群差異、成本與複雜性狀的環境影響。','番茄 Mi 抗根瘤線蟲基因可用相關標誌輔助選拔，之後仍須在適當環境驗證抗性；不能把檢出標誌等同所有條件下皆完全抗病。'),
'瓜整枝':('瓜類整枝須先了解品種在主蔓、子蔓與孫蔓的雌花或兩性花著生位置，保留足夠葉果比並改善通風採光。摘心、除側枝與疏果可調整源庫分配，但去葉過量會減糖、日燒及降低產量。','部分甜瓜可保留固定節位結果側蔓，一果一蔓或一株一果；西瓜可留主蔓與強子蔓，苦瓜常搭棚留蔓，不能用同一整枝模式處理所有瓜類。'),
'逆境':('逆境是使植物偏離適生條件、妨礙生長與繁殖的外界因素。非生物逆境可引發膜傷害、活性氧與水分失衡，植物以氣孔調節、滲透調節、抗氧化與形態適應降低損害，但耐受有上限。','熱帶蔬菜低溫時會發生膜功能異常、葉斑與生長停頓；選耐寒品種、避寒播期、覆蓋及根域保溫，比事後大量追肥有效。'),
}
def make(name, intro, rows):
    out=['# '+name,'',intro,'','> 「配分重點」為依題意擬定的建議得分項目，非校方評分規準。題幹採摘要，原卷為準。各題均可獨立閱讀；反覆出現的基礎原理在各題保留，以便逐卷練習。','']
    year=None
    for y,q,title,answer,mods,points in rows:
        if y!=year:
            out+=['## '+str(y)+' 學年度',''];year=y
        out+=['### '+q+'、'+title,'','**完整申論答案：**'+answer,'']
        for m in mods:
            a,b=MODULES[m];out+=['**原理與解析：**'+a,'','**實例：**'+b,'']
        if not mods: out+=['**解析與實例：**本題以各項的定義、構造或原文脈絡為判準；應將名稱與功能成對說明，例子已列於答案中，不可僅列名詞而不交代差異。','']
        out+=['**配分重點：**'+points,'']
    (ROOT/(name+'.md')).write_text('\n'.join(out),encoding='utf-8')
if __name__=='__main__':
    for f in sorted(Path(__file__).parent.glob('資料_*.py')):
        exec(compile(f.read_text(),str(f),'exec'))
